private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Check if the index is within the bounds of the buffer
    if (i < 0 || i >= bb.length()) {
        throw new IndexOutOfBoundsException("Index out of bounds");
    }

    // Check if the string buffer is null
    if (sb == null) {
        throw new NullPointerException("String buffer is null");
    }

    // Decode the octets to characters using the UTF-8 decoding
    char[] chars = decodeUtf8(bb, i);

    // Append the characters to the string buffer
    sb.append(chars);

    // Return the index to the next unchecked character in the string to decode
    return i + chars.length;
}

public void enlarge(final int size) {
	if (size < 0) {
		throw new IllegalArgumentException("The size parameter must be non-negative.");
	}

	if (this.data.length < this.position + size) {
		int newSize = this.data.length * 2;
		while (newSize < this.position + size) {
			newSize *= 2;
		}
		this.data = Arrays.copyOf(this.data, newSize);
	}
}

