/**
 * Construct a complete bipartite graph
 */
@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Step 1: Validate input
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and result map must not be null");
    }

    // Step 2: Generate vertices and edges
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        String label = entry.getKey();
        V vertex = entry.getValue();
        if (!target.containsVertex(vertex)) {
            target.addVertex(vertex);
        }
        for (int i = 0; i < resultMap.size(); i++) {
            String otherLabel = resultMap.keySet().toArray(new String[0])[i];
            if (!label.equals(otherLabel)) {
                V otherVertex = resultMap.get(otherLabel);
                if (!target.containsVertex(otherVertex)) {
                    target.addVertex(otherVertex);
                }
                target.addEdge(vertex, otherVertex, label + "-" + otherLabel);
            }
        }
    }
}

