import java.util.Stack;

public class DiagnosticContext {
    private static final String DEFAULT_CONTEXT = "";
    private static final Stack<String> diagnosticContextStack = new Stack<>();

    public static String peek() {
        if (diagnosticContextStack.isEmpty()) {
            return DEFAULT_CONTEXT;
        }
        return diagnosticContextStack.peek();
    }

    public static void push(String message) {
        diagnosticContextStack.push(message);
    }

    public static String pop() {
        if (diagnosticContextStack.isEmpty()) {
            return DEFAULT_CONTEXT;
        }
        return diagnosticContextStack.pop();
    }
}

