protected void addToIndex(V sourceVertex, V targetVertex, E e) {

    // 1. Check if the source vertex is already present in the index
    if (!this.index.containsKey(sourceVertex)) {
        // If the source vertex is not present, create a new list and add the target vertex and edge
        List<IndexEntry<V, E>> targetVertices = new ArrayList<>();
        targetVertices.add(new IndexEntry<V, E>(targetVertex, e));
        this.index.put(sourceVertex, targetVertices);
    } else {
        // If the source vertex is already present, add the target vertex and edge to the existing list
        List<IndexEntry<V, E>> targetVertices = this.index.get(sourceVertex);
        targetVertices.add(new IndexEntry<V, E>(targetVertex, e));
    }

    // 2. Check if the target vertex is already present in the index
    if (!this.index.containsKey(targetVertex)) {
        // If the target vertex is not present, create a new list and add the source vertex and edge
        List<IndexEntry<V, E>> sourceVertices = new ArrayList<>();
        sourceVertices.add(new IndexEntry<V, E>(sourceVertex, e));
        this.index.put(targetVertex, sourceVertices);
    } else {
        // If the target vertex is already present, add the source vertex and edge to the existing list
        List<IndexEntry<V, E>> sourceVertices = this.index.get(targetVertex);
        sourceVertices.add(new IndexEntry<V, E>(sourceVertex, e));
    }

    // Increment the number of edges in the index
    this.numEdges++;
}

