public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i == str.length() - 1) {
                throw new Exception("Invalid escape sequence at end of string");
            }
            char nextCh = str.charAt(i + 1);
            if (nextCh == 'n') {
                sb.append('\n');
                i++;
            } else if (nextCh == 'r') {
                sb.append('\r');
                i++;
            } else if (nextCh == 't') {
                sb.append('\t');
                i++;
            } else if (nextCh == 'b') {
                sb.append('\b');
                i++;
            } else if (nextCh == 'f') {
                sb.append('\f');
                i++;
            } else if (nextCh == '\'') {
                sb.append('\'');
                i++;
            } else if (nextCh == '"') {
                sb.append('"');
                i++;
            } else if (nextCh == '\\') {
                sb.append('\\');
                i++;
            } else {
                throw new Exception("Invalid escape sequence");
            }
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

