public GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if(tour == null || tour.isEmpty()){
        throw new IllegalArgumentException("Tour must not be null or empty");
    }
    if(graph == null || graph.getEdgeSet().isEmpty()){
        throw new IllegalArgumentException("Graph must not be null or empty");
    }

    // Create a new graph path
    GraphPath<V,E> path = new GraphPath<V,E>();

    // Add the first vertex to the path
    V startVertex = tour.iterator().next().getOpposite(graph.getFirstVertex());
    path.addVertex(startVertex);

    // Loop through the edges in the tour
    for(E edge : tour){
        V currentVertex = edge.getOpposite(startVertex);
        path.addVertex(currentVertex);
        path.addEdge(edge);
        startVertex = currentVertex;
    }

    // Add the last vertex to the path
    V endVertex = tour.iterator().next().getOpposite(null);
    path.addVertex(endVertex);

    return path;
}

