public int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPool.size(); i++) {
        Constant_Info info = constantPool.get(i);
        if (info instanceof Constant_NameAndType_Info) {
            Constant_NameAndType_Info nameAndTypeInfo = (Constant_NameAndType_Info) info;
            if (nameAndTypeInfo.name.equals(name) && nameAndTypeInfo.descriptor.equals(descriptor)) {
                // If found, return the already existing Symbol
                return nameAndTypeInfo.getSymbol();
            }
        }
    }

    // If not found, create a new Symbol and add it to the constant pool
    Constant_NameAndType_Info newNameAndTypeInfo = new Constant_NameAndType_Info(name, descriptor);
    constantPool.add(newNameAndTypeInfo);
    return newNameAndTypeInfo.getSymbol();
}

private String unescapeId(String input) {
    if (input == null || input.isEmpty()) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i < input.length() - 1) {
                char nextChar = input.charAt(i + 1);
                if (nextChar == '\\') {
                    output.append(c);
                    i++;
                } else if (nextChar == 'u') {
                    if (i < input.length() - 4) {
                        String hex = input.substring(i + 2, i + 6);
                        try {
                            int codePoint = Integer.parseInt(hex, 16);
                            output.append(Character.toChars(codePoint));
                            i += 5;
                        } catch (NumberFormatException e) {
                            throw new IllegalArgumentException("Invalid Unicode escape sequence: " + hex);
                        }
                    } else {
                        throw new IllegalArgumentException("Incomplete Unicode escape sequence");
                    }
                } else {
                    output.append(c);
                }
            } else {
                throw new IllegalArgumentException("Incomplete escape sequence");
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

