    ListNodeImpl<E> next = node.next;
    if (prev == null && next == null) {
        return false;
    }
    if (prev == null) {
        first = next;
    } else {
        prev.next = next;
    }
    if (next == null) {
        last = prev;
    } else {
        next.prev = prev;
    }
    node.prev = null;
    node.next = null;
    return true;
}

