private String parseToken(final char[] terminators ){
    // initialize an empty string to store the token
    StringBuilder token = new StringBuilder();

    // iterate through the input string
    for (int i = 0; i < terminators.length; i++) {
        // if the current character is a terminator, return the token
        if (terminators[i] == input[i]`) {
            return token.toString();
        }
        // if the current character is not a terminator, add it to the token
        token.append(input[i]);
    }

    // if the loop completes without encountering a terminator, return the token
    return token.toString();
}

