private static Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Bounds list cannot be null or empty.");
    }

    List<Integer> suffixSum = new ArrayList<>(bounds.size());
    long sum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSum.add(sum);
    }

    return Pair.of(suffixSum, sum);
}

public static final <V>void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("The array cannot be null");
    }
    if (from < 0 || to < 0 || from > to || to >= arr.length) {
        throw new IllegalArgumentException("Invalid range");
    }
    int mid = (from + to) / 2;
    for (int i = from; i <= mid; i++) {
        int mirrorIndex = to - (i - from);
        V temp = arr[i];
        arr[i] = arr[mirrorIndex];
        arr[mirrorIndex] = temp;
    }
}

