/**
 * Selects a the specified row in the specified JTable and scrolls the specified JScrollPane to the newly selected row. More importantly, the call to repaint() delayed long enough to have the table properly paint the newly selected row which ma
 * @param row The row to select
 * @param table The JTable to select the row in
 * @param pane The JScrollPane to scroll to the selected row
 */
public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Table and pane must not be null");
    }

    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Row index out of bounds");
    }

    table.clearSelection();
    table.addSelectionInterval(row, row);

    pane.getVerticalScrollBar().setValue(table.getY() + table.getRowHeight() * row);

    try {
        Thread.sleep(100);
    } catch (InterruptedException e) {
        // Do nothing
    }

    table.repaint();
}

