private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true;
    }
    Set<V> neighbors = new HashSet<>(vertices);
    for (V vertex : vertices) {
        neighbors.addAll(graph.getNeighbors(vertex));
    }
    return vertices.equals(neighbors);
}

private List<Integer> computeLowerBounds(List<Integer> keys){
    if (keys == null || keys.isEmpty()) {
        throw new IllegalArgumentException("Keys must not be null or empty!");
    }

    List<Integer> lowerBounds = new ArrayList<Integer>(keys.size());

    int minKey = Collections.min(keys);
    int maxKey = Collections.max(keys);

    for (Integer key : keys) {
        int lowerBound = minKey;
        if (key > lowerBound) {
            lowerBound = key;
        }
        lowerBounds.add(lowerBound);
    }

    for (int i = 0; i < keys.size() - 1; i++) {
        if (lowerBounds.get(i) > lowerBounds.get(i + 1)) {
            lowerBounds.set(i + 1, lowerBounds.get(i));
        }
    }

    return lowerBounds;
}

