public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        throw new IllegalArgumentException("str and substring cannot be null");
    }
    if (index < 0 || index >= str.length()) {
        throw new IllegalArgumentException("index must be a valid index in the string");
    }
    if (substring.length() > (str.length() - index)) {
        return false;
    }
    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

private void append(LoggingEvent event) {
    if (event == null) {
        throw new IllegalArgumentException("Null event cannot be appended.");
    }

    String message = event.getMessage();
    if (message.isEmpty() || message.isBlank()) {
        throw new IllegalArgumentException("Message cannot be null or blank.");
    }

    synchronized (this) {
        for (LogManager logger : logManagers) {
            logger.add(Event.of(message, event.getLevel(), event.getLoggerName(), event.getMarker()));
        }
    }
}

public static String toString(final char ch) {
    if (ch < 0 || ch > 127) {
        throw new IllegalArgumentException("Invalid character: " + ch);
    }
    final String cache;
    if (ch < 128) {
        cache = CACHE[ch];
    } else {
        cache = null;
    }
    if (cache != null) {
        return cache;
    }
    return new String(new char[] { ch }, 0, 1);
}

private static final String[] CACHE = new String[128];
static {
    for (int i = 0; i < 128; i++) {
        CACHE[i] = new String(new char[] { (char) i }, 0, 1);
    }
}

